import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0024: Deterministic prompt budgeting and capability-gated model setup","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0024-deterministic-prompt-budgeting.md","filePath":"adrs/0024-deterministic-prompt-budgeting.md","lastUpdated":1789092097000}`),u={name:`adrs/0024-deterministic-prompt-budgeting.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[45]||=a(`<h1 id="adr-0024-deterministic-prompt-budgeting-and-capability-gated-model-setup" tabindex="-1">ADR-0024: Deterministic prompt budgeting and capability-gated model setup <a class="header-anchor" href="#adr-0024-deterministic-prompt-budgeting-and-capability-gated-model-setup" aria-label="Permalink to “ADR-0024: Deterministic prompt budgeting and capability-gated model setup”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-31 · Extends <a href="/adrs/0005-memory-architecture">ADR-0005</a>, <a href="/adrs/0006-mcp-integration">ADR-0006</a>, <a href="/adrs/0016-chat-content-pipeline">ADR-0016</a>, <a href="/adrs/0017-engine-agnostic-openai-dialect">ADR-0017</a>, and <a href="/adrs/0023-single-active-turn-and-engine-lifecycle">ADR-0023</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[3]||=i(`The selected model reports an optional `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[0]||=[i(`context`,-1)]]),_:1}),l[4]||=i(` window through `,-1),l[5]||=c(`code`,null,`ModelRef.contextLength`,-1),l[6]||=i(`, but the `,-1),r(m,{term:`shepherd`},{default:n(()=>[...l[1]||=[i(`Shepherd`,-1)]]),_:1}),l[7]||=i(` currently assembles all eligible history and estimates only message text plus tool-schema characters. The actual request also contains system instructions, memory, image `,-1),r(m,{term:`token`},{default:n(()=>[...l[2]||=[i(`tokens`,-1)]]),_:1}),l[8]||=i(`, tool schemas, assistant tool-call IDs and arguments, tool results, role wrappers, and an output allowance. A character-only gauge can therefore say a request fits while the engine rejects it or silently truncates it.`,-1)]),l[46]||=a(`<p>The tool loop makes trimming structural. An assistant message containing <code>tool_calls</code> and the corresponding <code>role: tool</code> results form one protocol unit. Dropping only one side produces invalid or misleading history. M6 adds a memory digest to the system prompt, so prompt budgeting must be deterministic and tested before that content joins the request.</p><p>Rolling-summary compaction remains parked. MVP needs a transparent suffix-selection policy that is cheap, repeatable, and honest when even the newest exchange is too large.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="one-versioned-budget-policy" tabindex="-1">One versioned budget policy <a class="header-anchor" href="#one-versioned-budget-policy" aria-label="Permalink to “One versioned budget policy”">​</a></h3><p><code>GoatInference</code> owns a pure <code>PromptBudgeter</code> beside the canonical request types. Given the same model, policy version, system prompt, tool schemas, and ordered exchanges, it produces the same <code>PromptPlan</code> and <code>PromptBudgetReport</code>. It performs no file, network, database, or UI work.</p><p>For MVP policy version 1:</p><ol><li><code>windowTokens</code> is the selected <code>ModelRef.contextLength</code> when it is positive. If the engine omits it, GOAT uses a conservative <strong>8,192-token fallback</strong> and marks the source as estimated in the report. It never substitutes a larger value for a positive engine-reported window.</li><li><code>requestedOutputTokens</code> is the request override when present, otherwise the selected effort&#39;s <code>maxTokens</code>.</li><li><code>outputReserve</code> is <code>min(requestedOutputTokens, windowTokens / 2)</code>. The effective <code>max_tokens</code> sent to the engine is this reserve, so the engine cannot consume capacity promised to the input. Any clamp is reported.</li><li><code>safetyReserve</code> is five percent of the window, clamped to <strong>256...2,048 tokens</strong>. It covers chat-template markers, tokenizer variance, and engine-specific framing.</li><li><code>inputBudget = windowTokens - outputReserve - safetyReserve</code>. A non-positive budget is a local, actionable error. GOAT does not send a request it already knows cannot fit.</li></ol><p>No user setting silently changes these constants. Changing the fallback, estimator, reserve formula, or truncation order increments the policy version and updates its fixture tests.</p><h3 id="model-support-is-transport-wide-not-a-family-allow-list" tabindex="-1">Model support is transport-wide, not a family allow-list <a class="header-anchor" href="#model-support-is-transport-wide-not-a-family-allow-list" aria-label="Permalink to “Model support is transport-wide, not a family allow-list”">​</a></h3>`,9),c(`p`,null,[l[14]||=i(`Every model exposed by an `,-1),r(m,{term:`openai-compatible`},{default:n(()=>[...l[9]||=[i(`OpenAI-compatible`,-1)]]),_:1}),l[15]||=i(` engine uses the same chat, streaming, `,-1),r(m,{term:`tool`},{default:n(()=>[...l[10]||=[i(`tools`,-1)]]),_:1}),l[16]||=i(`, `,-1),r(m,{term:`vision-model`},{default:n(()=>[...l[11]||=[i(`vision`,-1)]]),_:1}),l[17]||=i(`, and prompt-budget path. `,-1),r(m,{term:`model`},{default:n(()=>[...l[12]||=[i(`Model`,-1)]]),_:1}),l[18]||=i(` names never select request fields. DeepSeek, Qwen, Gemma, Llama, Phi, gpt-oss, Mistral and Devstral, Nemotron, MiniMax, Kimi, Hunyuan, Ling, GLM, Step, MiMo, and other compatible models therefore receive the same generic `,-1),r(m,{term:`effort`},{default:n(()=>[...l[13]||=[i(`Effort`,-1)]]),_:1}),l[19]||=i(` presets and effective output clamp.`,-1)]),l[47]||=c(`p`,null,`The vision-name heuristic is presentation metadata only. It can add a label or warning, but it never strips a user-selected image or blocks the generic multimodal content-array request.`,-1),c(`p`,null,[l[21]||=i(`Dedicated coding variants, including Devstral, Qwen Coder, DeepSeek Coder, Codestral, Code Llama, StarCoder, Granite Code, CodeGemma, OpenCoder, and Kimi Dev, lead the model picker and are preferred only when no saved default remains valid. This is presentation and first-run selection policy. A `,-1),l[22]||=c(`code`,null,`coder`,-1),l[23]||=i(` name never enables tools, `,-1),r(m,{term:`thinking`},{default:n(()=>[...l[20]||=[i(`reasoning`,-1)]]),_:1}),l[24]||=i(`, vision, fill-in-the-middle, or a provider field.`,-1)]),l[48]||=a(`<p>The former Qwen3 <code>/no_think</code> and <code>/think</code> name-derived prompt mutation is removed. It made one family appear privileged and could not prove the active template accepted the control. Every native request control now requires explicit metadata from the active engine, except an explicit engine profile selected by the user. The <strong>Qwen local chat template</strong> profile is such a contract: it may send Qwen&#39;s documented <code>chat_template_kwargs</code> and replay prior assistant reasoning in <code>reasoning_content</code>; a model ID can never enable it.</p><h3 id="probe-selected-model-capabilities-before-sending" tabindex="-1">Probe selected-model capabilities before sending <a class="header-anchor" href="#probe-selected-model-capabilities-before-sending" aria-label="Permalink to “Probe selected-model capabilities before sending”">​</a></h3><p>Startup, engine changes, and model changes perform a bounded, metadata-only handshake for the selected model. The composer displays a compact progress indicator and remains disabled while the handshake is pending. A timeout, unsupported endpoint, malformed body, or absent capability field resolves to the generic-compatible state. It never changes a healthy engine to offline and never prevents ordinary chat after the bound expires.</p><p><code>GET /v1/models</code> remains the required catalog and can contribute non-standard context and capability fields when present. GOAT then uses only the adapter selected by an explicit engine preset:</p><table tabindex="0"><thead><tr><th>Adapter</th><th>Optional metadata call</th><th>Accepted evidence</th></tr></thead><tbody><tr><td>Generic, oMLX, vMLX, custom</td><td><code>GET /v1/models/{model-id}</code></td><td>Explicit context, capability, supported-parameter, and allowed-value fields only</td></tr><tr><td>LM Studio</td><td><code>GET /api/v1/models</code></td><td>Context, vision, positive tool-training hint, and reasoning availability; native-chat reasoning options do not prove a Chat Completions field</td></tr><tr><td>Ollama</td><td><code>POST /api/show</code> and <code>GET /api/ps</code></td><td>Model capabilities and declared/effective context; <code>thinking</code> plus Ollama&#39;s documented OpenAI-compatible contract proves <code>reasoning_effort</code> with <code>none</code>, <code>low</code>, <code>medium</code>, <code>high</code>, and <code>max</code></td></tr><tr><td>llama.cpp</td><td><code>GET /props?model=...</code></td><td>Effective context, vision, complete tool-template support, and <code>supports_reasoning_effort</code></td></tr></tbody></table><p>These calls contain the exact catalog model ID and no prompt, transcript, attachment, tool schema, or generated content. GOAT never generates a test completion, loads or unloads a model, requests llama.cpp slots, or probes an arbitrary vendor path for a Custom preset. Every metadata operation has a hard two-second wall-clock deadline and accepts at most 256 KiB (1 MiB for the health catalog and Ollama&#39;s detailed model response). It uses a dedicated ephemeral session with caches, cookies, and shared credential storage disabled. Oversized reads are explicitly cancelled. Redirects to a different normalized HTTP origin are rejected so an engine credential cannot escape its configured host. The redirect delegate is immutable after initialization; that invariant is the reason for its narrow <code>@unchecked Sendable</code> conformance.</p>`,6),c(`p`,null,[r(m,{term:`engine`},{default:n(()=>[...l[25]||=[i(`Engine`,-1)]]),_:1}),l[26]||=i(` roots must be HTTP or HTTPS URLs with a host and no URL userinfo, query, or fragment; API credentials have one separate field. Diagnostics contain only a sanitized host and effective port. Model IDs are opaque percent-encoded path components, including dot-only values. Catalogs are capped at 1,024 entries, model IDs at 512 UTF-8 bytes, duplicate IDs are removed, and control-bearing IDs are ignored before the catalog reaches UI or logs.`,-1)]),c(`p`,null,[l[28]||=i(`Fallback discovery is scoped by preset: `,-1),r(m,{term:`omlx`},{default:n(()=>[...l[27]||=[i(`oMLX`,-1)]]),_:1}),l[29]||=i(`/vMLX use ports 8000/8001, Ollama 11434, LM Studio 1234, and llama.cpp 8080. This prevents a provider-specific adapter from issuing its metadata calls to an unrelated service. Custom remains generic. Capability results are not retained in an engine-wide model cache; every explicit model selection performs the requested fresh bounded probe, while the current catalog retains the result for request snapshots and display. Navigating between chats that resolve to the same model does not repeat the network check or disable the composer.`,-1)]),c(`p`,null,[l[31]||=i(`Capabilities are tri-state: supported, unsupported, or unknown. Unknown preserves the portable request path. Generic capability arrays provide positive evidence only because their omissions are not standardized; absence becomes unsupported only in a documented exhaustive adapter such as Ollama. Explicitly unsupported tool-template metadata omits `,-1),r(m,{term:`mcp`},{default:n(()=>[...l[30]||=[i(`MCP`,-1)]]),_:1}),l[32]||=i(` schemas for that model; a training-quality hint does not. Vision metadata improves the badge and warning, but never silently deletes a user-selected image.`,-1)]),l[49]||=a(`<p>The selected model&#39;s immutable capability snapshot is copied into every <code>GenerationRequest</code>. A later model or engine change therefore cannot alter a suspended request. Model selection has one MainActor mutation path and a separate monotonic probe revision. A stale, cancelled, or previous-engine probe cannot publish into the current catalog.</p><p>Every model receives generic temperature and output-budget effort presets. <code>reasoning_effort</code> crosses the wire only when metadata explicitly advertises that exact parameter, reasoning support is positive and unambiguous, and the value is in the advertised or adapter-documented set. Graze selects the lowest allowed value, Summit the highest, and Trot/Climb the nearest allowed medium/high value. Missing or conflicting evidence emits no native field.</p><p>Incoming reasoning is normalized from <code>reasoning_content</code>, <code>reasoning</code>, <code>thinking</code>, inline <code>&lt;think&gt;</code> tags, and supported typed content parts. It is persisted locally with the transcript for user disclosure. The generic path never replays it. The explicit Qwen local chat-template profile is the narrowly scoped exception: the prompt budget includes each assistant trace and the wire encoder returns it only in the documented <code>reasoning_content</code> field. That keeps Qwen&#39;s preserved-thinking contract separate from dialects that require prior analysis to be removed.</p><h3 id="estimate-the-complete-request" tabindex="-1">Estimate the complete request <a class="header-anchor" href="#estimate-the-complete-request" aria-label="Permalink to “Estimate the complete request”">​</a></h3><p>The estimate covers every item that crosses the wire or consumes model context:</p>`,5),c(`ul`,null,[c(`li`,null,[l[34]||=i(`The complete system turn: GOAT preamble, date/environment, `,-1),r(m,{term:`pen`},{default:n(()=>[...l[33]||=[i(`Pen`,-1)]]),_:1}),l[35]||=i(` instructions, and the M6 memory snapshot.`,-1)]),l[36]||=c(`li`,null,`Every enabled tool's name, description, parameter-schema JSON, and request wrappers.`,-1),l[37]||=c(`li`,null,`Every role and content wrapper in retained chat turns.`,-1),l[38]||=c(`li`,null,`User and assistant text.`,-1),l[39]||=c(`li`,null,`Each image retained in a user turn.`,-1),l[40]||=c(`li`,null,`Assistant tool-call IDs, names, and argument JSON.`,-1),l[41]||=c(`li`,null,`Tool-result IDs, text, error text, and wrappers.`,-1)]),l[50]||=c(`p`,null,`Natural text uses an adaptive UTF-8 estimate: a two-bytes-per-token floor, explicit punctuation and non-ASCII units, and byte-for-byte charging for long unbroken encoded-looking runs. Untrusted protocol fields, including tool schemas, arguments, identifiers, and results, are charged at one token per UTF-8 byte. Fixed structural overhead covers request wrappers. Images use a deterministic reserve derived from decoded pixel dimensions, with a byte-size fallback when metadata cannot be read. An image never has zero cost.`,-1),l[51]||=c(`p`,null,[i(`These rules are deliberately cautious across popular tokenizer families, but they are still estimates rather than tokenizer proofs. An unusual tokenizer can disagree. Exact server `),c(`code`,null,`usage`),i(` remains authoritative for the post-response meter, and a server may still reject a planned request that its own template expands beyond the reserve.`)],-1),c(`p`,null,[l[43]||=i(`Thinking text is excluded because GOAT does not replay it. UI-only metadata, timestamps, display names, and `,-1),r(m,{term:`paddock`},{default:n(()=>[...l[42]||=[i(`Paddock`,-1)]]),_:1}),l[44]||=i(` rendering state are also excluded because they do not cross the inference boundary.`,-1)]),l[52]||=a(`<h3 id="build-atomic-exchanges" tabindex="-1">Build atomic exchanges <a class="header-anchor" href="#build-atomic-exchanges" aria-label="Permalink to “Build atomic exchanges”">​</a></h3><p>History is normalized before selection:</p><ul><li>An <strong>exchange</strong> begins with a user turn and contains every following assistant turn up to, but not including, the next user turn.</li><li>An assistant turn containing tool calls plus every tool result linked to those calls is an indivisible <strong>assistant-tool group</strong>. The budgeter never retains an orphan result, removes a call while keeping its result, or splits the group across the trim boundary.</li><li>The in-progress user turn and any completed assistant-tool rounds that follow it form the newest exchange.</li><li>Invalid orphan tool data is rejected before budgeting rather than repaired by trimming.</li></ul><h3 id="preserve-a-recent-contiguous-suffix" tabindex="-1">Preserve a recent contiguous suffix <a class="header-anchor" href="#preserve-a-recent-contiguous-suffix" aria-label="Permalink to “Preserve a recent contiguous suffix”">​</a></h3><p>Selection proceeds in this order:</p><ol><li>Reserve output and safety capacity.</li><li>Include the system turn and all enabled tool schemas.</li><li>Include the newest user exchange.</li><li>Walk older exchanges from newest to oldest, adding each whole exchange while it fits. At the first exchange that does not fit, drop it and every older exchange. GOAT never skips a recent large exchange to resurrect disconnected older context.</li></ol><p>The system turn and newest exchange are therefore always represented. Older history is removed only as complete exchanges, and assistant-tool groups remain atomic inside every retained exchange.</p><p>The system turn, including the GOAT preamble and uncapped Pen instructions, is never truncated. Future memory content must arrive through its own documented cap. If the system turn, tool schemas, and the minimum valid representation of the newest exchange cannot fit together, planning fails locally with a component breakdown and an actionable suggestion, such as disabling tools or shortening Pen instructions. It does not silently discard system policy.</p><h3 id="explicit-oversized-newest-exchange-handling" tabindex="-1">Explicit oversized-newest-exchange handling <a class="header-anchor" href="#explicit-oversized-newest-exchange-handling" aria-label="Permalink to “Explicit oversized-newest-exchange handling”">​</a></h3><p>If the newest exchange is individually too large after older history has been removed, GOAT keeps its roles and protocol links but truncates payloads in this stable order until it fits:</p><ol><li>Tool-result bodies, oldest first, become head-and-tail excerpts.</li><li>Assistant text bodies, oldest first, become head-and-tail excerpts.</li><li>User images are omitted as whole image parts, oldest first. A text marker records each omitted image.</li><li>The newest user text is truncated last as a head-and-tail excerpt.</li></ol><p>Every excerpt or omission inserts a literal marker containing the omitted estimated-token count, and the marker itself is included in the next estimate. Tool-call IDs, tool names, tool-call argument JSON, result linkage, roles, and structural wrappers are never partially truncated. If those non-trimmable fields plus the minimum marked payload still exceed the input budget, planning fails locally rather than emitting invalid protocol history.</p><p>This is truncation, not summarization. GOAT never asks a model to invent a compressed replacement under this ADR.</p><h3 id="report-every-trim-decision" tabindex="-1">Report every trim decision <a class="header-anchor" href="#report-every-trim-decision" aria-label="Permalink to “Report every trim decision”">​</a></h3><p>Every plan carries a report with:</p><ul><li>Model ID, context-window value and source, policy version.</li><li>Requested and effective output reserve, safety reserve, and input budget.</li><li>Estimated input tokens before and after planning.</li><li>Retained and dropped exchange counts.</li><li>Truncated text fields, excerpt sizes, omitted images, and estimated tokens removed.</li><li>A failure component when no valid plan fits.</li></ul><p>When content changes, the Shepherd emits one non-model-visible inline notice per user turn and a detailed activity-log entry. Tool rounds may produce new reports as results grow, but the transcript notice is updated rather than appended repeatedly. The report feeds the preflight context meter; final server <code>usage</code>, when present, replaces the estimate after completion.</p><p>Trim notices are metadata and are not inserted into the model conversation. The explicit excerpt and image markers are model-visible because they replace omitted content, and their cost is already part of the plan.</p><h3 id="required-tests" tabindex="-1">Required tests <a class="header-anchor" href="#required-tests" aria-label="Permalink to “Required tests”">​</a></h3><p>Fixture and invariant tests cover reported and fallback context windows, output clamping, canonical schemas and ordering, high-entropy protocol estimates, model mismatches, contiguous suffix selection, linked tool histories, newest-exchange truncation order, image omission, invalid histories, non-trimmable metadata failures, deterministic repeated planning, capability isolation, coder ordering, provider metadata fixtures, stale and cancelled probe rejection, hard deadlines, isolated metadata sessions, endpoint/origin validation, catalog and ID bounds, safe model-ID encoding, vision non-gating, native-field gating, conflict handling, and reasoning-delta normalization. Successful fixtures assert that their reported estimate fits the policy input budget and that protocol links remain valid.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Predictable context overflow becomes a local deterministic planning result instead of an engine-specific surprise.</li><li>Popular model families remain supported through one generic OpenAI-compatible path; a preset adapter can only add a proven capability.</li><li>Dedicated coder variants are easier to find and become the fallback default without receiving guessed wire behavior.</li><li>A short selected-model loading phase buys deterministic request setup. Engines without richer metadata pay only the bounded failed probe and then use the generic path.</li><li>Tool-heavy and vision chats are budgeted honestly, including their non-text costs.</li><li>The newest request remains useful and protocol-valid while older exchanges fall away predictably.</li><li>The 8,192-token fallback and cautious estimates can leave some engine capacity unused, yet an unusual tokenizer or chat template can still exceed them. A future engine capability may supply a tokenizer-specific estimator behind the same plan and report surface.</li><li>Long-chat semantic compression is still absent. Rolling summaries remain a separate post-MVP decision.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Characters divided by four (rejected: undercounts JSON, wrappers, images, and many code-heavy prompts), letting the engine truncate (rejected: behavior varies and can split tool protocol), dropping individual messages (rejected: creates orphan tool results and incoherent exchanges), keeping any older unit that happens to fit (rejected: produces non-contiguous history), summarizing dropped history during send (rejected: adds latency, another model call, and nondeterminism), and requiring a model-specific tokenizer for MVP (rejected: incompatible with the engine-agnostic client and unavailable from many local servers).</p>`,24)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};